(function(w,d){
'use strict';
var STORY={"tr":{"ui":{"open":"BÜYÜK EKRANDA OKU","prev":"ÖNCEKİ","next":"SONRAKİ","close":"KAPAT","final":"FİNAL","readerTitle":"EduVerse · Kurucu Hikâyesi","parentTitle":"Anne ve babalara küçük bir ricam"},"chapters":[{"k":"01 · BEN KİMİM?","title":"Hayat okulundan gelen biri","short":"31 Mart 1970 İstanbul doğumluyum. Okul hayatım kısa sürdü; hayat okulu ise hiç bitmedi.","body":["Ben Tarkan. 31 Mart 1970 İstanbul doğumluyum.","Akademik anlamda uzun bir eğitim hayatım olmadı. İlkokulu bile zor şartlar altında tamamladım. Ama benim eğitimim orada bitmedi. Kendimi her zaman hayat okulunun öğrencisi olarak gördüm; kendi inancıma göre bu okulun insanın ölümüyle bile bitmediğine inanıyorum.","Hayatın çok farklı yüzlerini gördüm. Üvey anneyle de, üvey babayla da yaşadım. Yoksulluğu da gördüm, çok iyi maddi imkânlara sahip olduğum dönemleri de. Yeri geldi rahat yaşadım, yeri geldi çok ağır maddi zorluklar yaşadım.","Hayat bana ne getirirse getirsin, değiştirmemeye çalıştığım bir şey vardı: kimliğim ve karakterim. Çalışan oldum, yönetici oldum, patron oldum; yemek sektöründe, üretimde ve farklı işlerde çalıştım.","Almanya’da taksicilik yaparken sağlık sorunları yaşadım. Geçirdiğim ameliyat hayatımı değiştirdi ve sonunda daha çok evde yaşamaya başladım.","Bundan daha ağır kayıplarım da oldu. Sevdiğim bir kadından bir kızım dünyaya geldi. Kızımı kaybettim. Daha sonra annemi, babamı ve sevdiğim insanları da kaybettiğim dönemler oldu.","Bugün geriye baktığımda iyi veya kötü hiçbir dönemi tamamen anlamsız görmüyorum. Çünkü bütün bu yolların beni yıllar sonra hiç tahmin etmediğim bir kapının önüne getireceğini bilmiyordum.","O kapının adı daha sonra EduVerse olacaktı."]},{"k":"02 · HER ŞEY BİR DUA İLE BAŞLADI","title":"Kızıma göndermek istediğim küçük bir mesaj","short":"EduVerse bir şirket fikriyle değil, kızım için gökyüzüne göndermek istediğim küçücük bir duayla başladı.","body":["EduVerse büyük bir şirket fikriyle başlamadı. Bir oyun yapmaya da oturmadım. Kod bilmiyordum, yazılım bilmiyordum; bir uygulamanın nasıl yapıldığını dahi bilmiyordum.","Mayıs ayının başlarında bir gün evde otururken rahmetli kızımı düşündüm. Kızım için bir dua yazmak, onu bir kutuya koyup gökyüzüne göndermek ve sonra gökyüzünden ışıkların ya da duaların süzüldüğünü görmek istedim.","Benim için bunun anlamı çok basitti: “Seni unutmadım.”","Nasıl yapılacağını bilmediğim için internette gördüğüm yapay zekâ araçlarından birini açtım. İlk sorduğum şey “Türkçe biliyor musun?” oldu. “Evet” cevabını aldım ve karşımdaki sisteme bir makine gibi değil, birlikte çalıştığım bir arkadaş gibi davranmaya başladım.","Kızım için düşündüğüm o küçük dua fikrini anlattım. İlk oda ortaya çıktı. “Dua yukarı gitse olur mu?” dedim, oldu. “Mühürlense?” oldu. “Rengi değişse?” değişti. “Telefon ekranına uygun olabilir mi?” diye sordum ve onu da araştırmaya başladım.","Her cevabın ardından aklıma yeni bir soru geliyordu.","Farkında olmadan yalnızca bir dua hazırlamıyordum. Bir dünyanın ilk taşını koyuyordum."]},{"k":"03 · BİLMEDİĞİM BİR DÜNYAYI ÖĞRENMEK","title":"Oki’den robotlara uzanan yol","short":"Asset’in ne olduğunu bilmiyordum. Hata yaptım, kaybettim sandım, tekrar denedim; EduVerse böyle büyüdü.","body":["İlk odadan sonra duramadım. Bir oda daha yaptım. İlk dönemlerde düşüncelerim kendi inancımdan ve hayatımdan besleniyordu; bir ibadet odası oluşturdum ve küçük bir karakter yaptım. Adı Oki oldu.","Oki’nin rengini, boyunu, hareketlerini değiştirdim; ona yemek yedirmeyi, içirmeyi ve çocukla etkileşime girmesini denedim. Sonra başka oyunlara baktım ve kendi karakterimin çok zayıf kaldığını gördüm.","Bu kez karakter üretmeyi öğrenmeye başladım. “Asset” kelimesinin ne olduğunu bile bilmiyordum. Şeffaf arka planın neden gerektiğini bilmiyordum. Hepsini adım adım öğrendim ve onlarca farklı karakter görseli ürettim.","Sonra odalar büyüdü: yazılar, efektler, balonlar, puzzle, refleks oyunları, dil odaları… Türkçe, Almanca, İngilizce, Fransızca ve Arapça gibi farklı dilleri sisteme katmaya başladım.","Elbette işler sürekli yolunda gitmedi. Bir gün yanlış yere bastığım için bütün platform beyaz bir ekrana dönüştü. çalışmalarımın yok olduğunu sandım ve uzun saatler boyunca düzeltmeye çalıştım.","Sonradan çözümün ne kadar basit olduğunu öğrendim. Ama o 36 saat bana şunu öğretti: bilmemek utanılacak bir şey değildi; vazgeçmek benim için daha büyük problemdi.","O günden sonra her hata yeni bir ders oldu: FAILED. Tekrar dene. Tekrar düşün. Tekrar yap. Ve sonunda: PASSED.","EduVerse böyle büyüdü."]},{"k":"04 · BİR OYUNDAN DAHA FAZLASI","title":"Neden bütün çocuklar?","short":"Bir süre sonra kendime sordum: Bundan neden yalnızca benim gibi yaşayan çocuklar yararlansın?","body":["Başlangıçta yaptıklarım kendi hayatımdan ve inancımdan izler taşıyordu. Sonra kendime önemli bir soru sordum: “Bundan neden yalnızca benim gibi yaşayan çocuklar yararlansın?”","Bir çocuk Müslüman olmayabilir, başka bir ülkede yaşayabilir, başka bir dil konuşabilir veya başka bir kültürde büyüyebilir. Ama dürüstlük, arkadaşlık, paylaşmak, öğrenmek, düşünmek, iyilik yapmak, kendine güvenmek ve başkalarına saygı göstermek yalnızca bir dine ya da millete ait değildir.","Bunun üzerine EduVerse’in yönü değişti. İnançla ilgili odalar kaldı; çünkü onlar da benim hikâyemin bir parçasıydı. Fakat bu alanları ebeveyn kararına bırakan bir yapı kurdum.","Aynı zamanda herkese açık başka bir dünya büyüttüm: bulmacalar, refleks oyunları, dil çalışmaları, düşünmeyi gerektiren görevler ve çocuğun yalnızca ekrana dokunmasını değil, zaman zaman karar vermesini isteyen bölümler.","Bugün EduVerse 33 odalı bir platforma dönüştü. Her odanın farklı bir amacı var ve ben bunu kusursuz, bitmiş bir ürün olarak değil, sürekli gelişebilecek bir yapı olarak görüyorum.","Asıl hedefim çocuğun birkaç dakika oyalanması değil. Bir odadan çıktığında aklında küçücük de olsa iyi bir fikir kalması; bir arkadaşına daha iyi davranması, başka bir kültürü küçümsememesi, bir kelime öğrenmesi, bir problemi çözmesi veya kendine biraz daha güvenmesi.","Bunlardan yalnızca biri gerçekleşirse bile benim için o oda boşuna yapılmamış demektir."],"parent":["Çocuğunuzun ne oynadığını, ne izlediğini ve ne öğrendiğini mümkün olduğunca takip edin. Bazen onun yanında birkaç dakika oturmanız, ne yaptığını sormanız veya birlikte bir oyun oynamanız bile düşündüğünüzden çok daha değerlidir.","Ben EduVerse’i anne ve babanın yerini almak için değil, onların çocuğuyla kurduğu bağı desteklemek için yapmak istiyorum. Çünkü çocuklarımızın yalnızca eğlenmeye değil; dinlenmeye, anlaşılmaya, doğru örnekler görmeye ve bizim zamanımıza da ihtiyaçları var.","Bizde güzel bir söz vardır: “Ağaç yaşken eğilir.” Çocukken verilen küçük bir iyilik, küçük bir bilgi veya güzel bir davranış, yıllar sonra o insanın karakterinin bir parçası olabilir."]},{"k":"05 · EDUVERSE NEDEN ÜCRETLİ?","title":"Bir çocuk alırken başka bir çocuğu unutmamak","short":"Platformu yaşatmak için ücret gerekti; ama bunun yanında Askıda EduVerse ve İyilik Fonu fikri doğdu.","body":["Başlangıçta EduVerse’i tamamen ücretsiz yapmak istedim. Çünkü dünyada maddi imkânları aynı olmayan milyonlarca aile olduğunu biliyorum.","Fakat zamanla şunu gördüm: bir platformu yapmak başka şey, onu yıllarca yaşatabilmek başka şey. Yeni odaların, yeni özelliklerin, teknik hizmetlerin, mağaza sistemlerinin ve ileride kullanmak istediğim konuşabilen karakterlerin gerçek maliyetleri var.","Bu nedenle abonelik yerine mümkün olduğunca sade bir sistem düşünmeye başladım. İnsanları her ay ödeme yapmak zorunda bırakmak istemedim. İsteyen belirli oda paketlerini alabilsin, isteyen bir defa Tam Erişim alsın ve kullanabilsin.","Fakat bunun yanında benim için daha önemli başka bir düşünce doğdu: Askıda EduVerse. Bir aile kendi çocuğu için EduVerse alırken isterse imkânı olmayan başka bir çocuk için de bir erişim bırakabilsin.","EduVerse büyüdüğünde gelir-gider yapısı kesinleştiğinde, benim payımdan da belirli bir bölümün çocuklara ayrıldığı şeffaf bir İyilik Fonu oluşturmak istiyorum. Küçük bir miktar bir öğüne, daha büyük bir fon bir öğrencinin eğitimine, daha da büyüğü başka hayatlara katkı sağlayabilir.","Bunu bütün dünyanın katılabildiği bir iyilik hareketine dönüştürmek istiyorum. Dünya Merkezi’nde katkı sağlayan ülkelerin görünmesi fikri de buradan doğdu.","Ailelerin gereksiz kişisel verilerini toplamayı istemiyorum. Çocuğun gelişim bilgisini mümkün olduğunca ailenin kendi elinde tutan sistemler tasarladım; aile raporunun PDF olarak alınabilmesi bunun parçalarından biri.","EduVerse büyürse yalnızca daha çok satmış olmak istemiyorum. Daha çok çocuğa ulaşmış olmak istiyorum."]},{"k":"06 · BUGÜN VE YARIN","title":"Küçük bir odadan başlayan büyük bir hayal","short":"Küçük bir laptop, sekiz aylık emek ve hiç durmayan fikirlerle başlayan yol burada bitmiyor.","body":["Bu projeyi büyük bir ofiste kurmadım. Arkamda büyük bir yazılım ekibi veya güçlü bilgisayarlardan oluşan bir laboratuvar yoktu.","Sağlık nedeniyle evinden çıkamayan ve devlet desteğiyle yaşayan bir insan olarak küçük bir Lenovo laptopun karşısına oturdum. Bazen saatlerce, bazen geceler boyunca çalıştım. Yeri geldi bir kek ve meyve suyuyla devam ettim, yeri geldi iyi bir iş çıkardığımı düşünüp kendimi güzel bir yemekle ödüllendirdim.","Sekiz ay boyunca neredeyse her gün bu dünyanın içinde yaşadım. Bir dizi, pencereden gördüğüm bir ağaç veya bir kitapta okuduğum tek bir cümle yeni bir fikrin başlangıcı olabiliyordu.","Bugün bile oturup sıfırdan profesyonel bir kod yazamam. Ama bir aracı iyi kullanabilmenin de bir beceri olduğunu öğrendim. HTML, JavaScript, Python, Node.js, Android geliştirme araçları ve daha önce adını bile bilmediğim birçok sistemle çalışmayı öğrendim.","Daha ileri seviyede Unity, Unreal Engine veya benzeri profesyonel oyun motorlarıyla yapılabilecek şeylerin çok daha büyük olduğunu da biliyorum. Onları zamanla öğrenebilir veya ileride doğru insanlarla birlikte çalışabilirim.","Mağaza test aşamasına geldiğimde başka bir hayat dersi yaşadım. Yardım beklediğim bazı yakın insanlardan destek bulamadım; buna karşılık Çin’den, Almanya’dan, İtalya’dan, Fransa’dan, Amerika’dan ve dünyanın başka yerlerinden hiç tanımadığım insanlar test sürecime katıldı. EduVerse bugün bu aşamaya geldiyse, onların da bu hikâyede küçük bir payı var. Hepsine teşekkür ediyorum.","Ve bu yol burada bitmiyor. Oki Dede gelecek planlarım arasında; çocuklara uzun masallar anlatan ve onlarla konuşabilen yaşlı robot hayalim var. Çocukların oyun oynarken kodlama mantığını hissetmesini sağlayacak başka projelerim ve henüz açıklamak istemediğim daha büyük fikirlerim var.","Belki EduVerse çok büyür, belki küçük kalır. Ama bir çocuk bile buradan güzel bir şey alırsa benim için değeri vardır. Bazen büyük değişiklikler çok küçük bir başlangıçtan doğar.","EduVerse de öyle doğdu: bir babanın kaybettiği kızına göndermek istediği küçük bir duadan.","Bugün o dua artık yalnızca gökyüzüne gitmiyor. Ben onun dünyanın dört bir yanındaki çocuklara ulaşmasını istiyorum."]}],"final":{"k":"AYLİN'İME","title":"","body":["Aylin’im,","Bu hikâyenin nereden başladığını belki şimdi daha iyi anlatabiliyorum.","Her şey sana göndermek istediğim küçücük bir duayla başladı. Seni özlediğimi, seni unutmadığımı bir şekilde gökyüzüne söylemek istemiştim. O gün bunun bir oyuna, bir platforma veya böyle büyük bir hayale dönüşeceğini bilmiyordum.","Seni geri getiremem. Bunu biliyorum. Ama sana olan sevgimi kaybetmek yerine, onu başka bir şeye dönüştürmeye çalıştım.","Bir çocuğun yüzü gülerse, bir çocuk yeni bir şey öğrenirse, bir anne veya baba çocuğuyla biraz daha güzel vakit geçirirse, imkânı olmayan bir çocuğa bir kapı açılırsa, yapılan küçücük bir iyilik başka bir iyiliğe dönüşürse… orada senden de bir parça olsun istiyorum.","EduVerse’in ilk odası senin için açıldı. İlk dua senin için gökyüzüne gönderildi. Ve ne kadar büyürse büyüsün, bu hikâyenin başlangıç noktasında hep sen olacaksın.","Hayatımda yapamadığım, yetişemediğim veya eksik bıraktığım ne varsa değiştiremem. Ama bundan sonra yapabileceklerimi iyiliğe çevirmeye çalışabilirim.","Belki bir gün bu platform dünyanın başka bir köşesinde hiç tanımadığım bir çocuğun hayatına küçücük de olsa güzel bir şey bırakır.","O zaman içimden yine sana şunu söyleyeceğim:","“Bak Aylin’im… O küçücük dua buraya kadar geldi.”","Seni unutmadım. Unutmayacağım.","Baban"]}},"en":{"ui":{"open":"READ ON LARGE SCREEN","prev":"PREVIOUS","next":"NEXT","close":"CLOSE","final":"FINAL","readerTitle":"EduVerse · Founder Story","parentTitle":"A small request to parents"},"chapters":[{"k":"01 · WHO AM I?","title":"A student of the school of life","short":"I was born in Istanbul on 31 March 1970. My formal schooling was short; the school of life never ended.","body":["I’m Tarkan. I was born in Istanbul on 31 March 1970.","I did not have a long formal education. I completed even primary school under difficult circumstances. But my education did not end there. I have always seen myself as a student of the school of life, and in accordance with my faith I believe that this school does not simply end with death.","I have seen very different sides of life. I lived with a stepmother and a stepfather. I knew poverty, but I also had periods of very good financial means. There were times when I lived comfortably, and times when I went through severe financial hardship.","Whatever life brought me, there was one thing I tried not to surrender: my identity and my character. I was an employee, a manager and an employer; I worked in food, production and many other jobs.","While driving a taxi in Germany, I developed health problems. The effects of an operation changed my life and eventually led me to spend much more of my time at home.","There were losses far heavier than that. I had a daughter with a woman I loved. I lost my daughter. Later I also went through periods in which I lost my mother, my father and people I loved.","Looking back today, I do not see any good or bad period of my life as completely meaningless. I had no idea that all those roads would one day bring me to a door I had never imagined.","That door would later be called EduVerse."]},{"k":"02 · IT BEGAN WITH A PRAYER","title":"A small message I wanted to send to my daughter","short":"EduVerse did not begin as a company idea. It began with a tiny prayer I wanted to send to the sky for my daughter.","body":["EduVerse did not begin as a big company idea. I did not sit down to make a game. I knew no coding, no software, and not even how an app was made.","One day in early May, while sitting at home, I thought about my late daughter. I wanted to write a prayer for her, place it in a box, send it upward and see lights or prayers drift back down from the sky.","For me, its meaning was simple: “I have not forgotten you.”","Because I did not know how to make it, I opened one of the AI tools I had seen online. My first question was, “Do you speak Turkish?” The answer was yes, and I began to treat the system not merely as a machine but as a companion I was working with.","I told it about the little prayer I had imagined for my daughter. The first room appeared. “Can the prayer rise upward?” It could. “Can it be sealed?” It could. “Can the color change?” It changed. “Can this fit a phone screen?” I began researching that too.","Every answer created a new question in my head.","Without realizing it, I was no longer making only a prayer. I was laying the first stone of a world."]},{"k":"03 · LEARNING A WORLD I DIDN’T KNOW","title":"From Oki to robots","short":"I did not even know what an asset was. I made mistakes, thought I had lost everything, tried again—and EduVerse grew that way.","body":["After the first room, I could not stop. I made another room. At first my ideas naturally came from my own life and faith; I created a worship room and then a small character. His name became Oki.","I changed Oki’s color, size and movements; I tried to feed him and let him interact with a child. Then I looked at other games and saw how weak my own character still was.","So I began learning how characters were made. I did not even know what the word “asset” meant. I did not know why an image needed a transparent background. I learned all of it step by step and created dozens of character images.","Then the rooms grew: text, effects, balloons, puzzles, reflex games and language rooms. I began adding Turkish, German, English, French and Arabic.","Of course, things did not always go well. One day, after clicking the wrong place, the entire platform turned into a white screen. I thought all my work was gone and spent long hours trying to repair it.","Later I learned how simple the solution actually was. But those 36 hours taught me something important: not knowing was nothing to be ashamed of; giving up would have been the bigger problem for me.","From then on, every error became a lesson: FAILED. Try again. Think again. Build again. And eventually: PASSED.","That is how EduVerse grew."]},{"k":"04 · MORE THAN A GAME","title":"Why all children?","short":"At some point I asked myself: Why should only children who live like me benefit from this?","body":["At first, what I built naturally carried traces of my own life and faith. Then I asked myself an important question: “Why should only children who live like me benefit from this?”","A child may not be Muslim. They may live in another country, speak another language or grow up in another culture. But honesty, friendship, sharing, learning, thinking, kindness, self-confidence and respect for other people do not belong to only one religion or one nation.","That changed the direction of EduVerse. Faith-related rooms remained because they are also part of my story, but I built them in a way that leaves those choices to parents.","At the same time, I expanded a world open to everyone: puzzles, reflex games, language practice, tasks that require thought, and sections that ask a child not only to tap a screen but sometimes to make a decision.","Today EduVerse has become a platform with 33 rooms. Every room has a different purpose, and I do not see it as a perfect, finished product but as a structure that can keep developing.","My real goal is not to keep a child busy for a few minutes. I want a small good idea to remain in their mind when they leave a room: treating a friend better, not looking down on another culture, learning a word, solving a problem, or trusting themselves a little more.","If even one of those things happens, that room was not built in vain for me."],"parent":["Please pay attention, as much as you can, to what your child plays, watches and learns. Sitting beside them for a few minutes, asking what they are doing or playing something together can be more valuable than you think.","I do not want EduVerse to replace a mother or father. I want it to support the bond they build with their child. Children need not only entertainment, but also to be heard, understood, shown good examples and given our time.","We have a saying: “A tree is bent while it is young.” A small kindness, a little knowledge or a good behavior learned in childhood can become part of that person’s character years later."]},{"k":"05 · WHY DOES EDUVERSE COST MONEY?","title":"Not forgetting another child when one child receives access","short":"Keeping the platform alive costs money; that is why the ideas of Suspended EduVerse and the Goodness Fund were born.","body":["At first I wanted EduVerse to be completely free because I know that millions of families around the world do not have the same financial means.","Over time I understood something: building a platform is one thing; keeping it alive for years is another. New rooms, new features, technical services, store systems and future speaking characters all have real costs.","So instead of a subscription, I began thinking about the simplest system I could. I did not want to force people into a monthly payment. Those who want it can buy selected room packages; those who prefer can buy Full Access once and use it.","But another idea became even more important to me: Suspended EduVerse. When a family buys EduVerse for their own child, they should be able, if they wish, to leave access for another child who cannot afford it.","When EduVerse grows and its income and expenses become clear, I also want to create a transparent Goodness Fund in which a defined part of my own share is set aside for children. A small amount may cover a meal; a larger fund may support a student’s education; a still larger one may touch other lives.","I want this to become a kindness movement in which the whole world can take part. The idea of showing contributing countries in the World Hub came from this thought.","I also do not want to collect unnecessary personal data from families. I designed systems intended to keep information about a child’s development as much as possible in the family’s own hands; the downloadable family PDF report is one part of that.","If EduVerse grows, I do not want that to mean only that I sold more. I want it to mean that I reached more children."]},{"k":"06 · TODAY AND TOMORROW","title":"A big dream that began in a small room","short":"A small laptop, eight months of work and ideas that would not stop—this road is not ending here.","body":["I did not build this project in a large office. There was no big software team behind me and no laboratory full of powerful computers.","As someone who, for a period, could not leave home because of health problems and was living on state support, I sat in front of a small Lenovo laptop. Sometimes I worked for hours, sometimes through the night. There were days when I carried on with only a piece of cake and a fruit drink, and days when I rewarded good work with a good meal.","For eight months I lived inside this world almost every day. A series, a tree outside the window or a single sentence in a book could become the beginning of a new idea.","Even today I cannot sit down and write professional code from scratch. But I learned that knowing how to use a tool well is also a skill. I learned to work with HTML, JavaScript, Python, Node.js, Android development tools and many systems whose names I had never known before.","I also know that professional engines such as Unity or Unreal Engine can make much more advanced games possible. I can learn those over time or one day work with the right people.","When the store testing stage arrived, I learned another lesson about life. I did not receive support from some people close to me whom I expected to help. Yet people I had never met—from China, Germany, Italy, France, the United States and other parts of the world—joined my testing process. If EduVerse has reached this stage today, they also have a small part in this story. I thank them.","And the road does not end here. Oki Dede is among my future plans: an elderly robot I imagine telling children long stories and speaking with them. I have other projects in mind that will let children feel the logic of coding while they play, and larger ideas I am not ready to reveal yet.","Maybe EduVerse will grow very large. Maybe it will remain small. But if even one child receives something good from it, it has value to me. Sometimes big changes begin with a very small start.","EduVerse began that way: with a small prayer a father wanted to send to the daughter he had lost.","Today that prayer is no longer going only toward the sky. I want it to reach children all around the world."]}],"final":{"k":"FOR AYLIN","title":"","body":["My Aylin,","Perhaps now I can explain more clearly where this story began.","Everything started with a tiny prayer I wanted to send to you. I wanted, somehow, to tell the sky that I missed you and had not forgotten you. That day I did not know it would turn into a game, a platform, or a dream this large.","I cannot bring you back. I know that. But instead of losing the love I have for you, I tried to turn it into something else.","If a child smiles, learns something new, spends a little better time with a mother or father, if a door opens for a child who has less, if one small act of kindness turns into another… I want there to be a piece of you in that.","EduVerse’s first room opened for you. The first prayer was sent to the sky for you. And no matter how much it grows, you will always be at the starting point of this story.","I cannot change what I could not do, could not reach, or left incomplete in my life. But I can try to turn what I can still do into something good.","Maybe one day this platform will leave one small good thing in the life of a child I have never met, somewhere else in the world.","Then I will say to you again inside myself:","“Look, my Aylin… that tiny prayer came all the way here.”","I have not forgotten you. I never will.","Dad"]}},"de":{"ui":{"open":"AUF GROSSEM BILDSCHIRM LESEN","prev":"ZURÜCK","next":"WEITER","close":"SCHLIESSEN","final":"FINALE","readerTitle":"EduVerse · Gründergeschichte","parentTitle":"Eine kleine Bitte an Mütter und Väter"},"chapters":[{"k":"01 · WER BIN ICH?","title":"Ein Schüler der Lebensschule","short":"Ich wurde am 31. März 1970 in Istanbul geboren. Meine Schulzeit war kurz; die Lebensschule endete nie.","body":["Ich bin Tarkan. Ich wurde am 31. März 1970 in Istanbul geboren.","Meine formale Schulbildung war nicht lang. Selbst die Grundschule schloss ich unter schwierigen Bedingungen ab. Aber meine Bildung endete dort nicht. Ich habe mich immer als Schüler der Lebensschule gesehen, und nach meinem eigenen Glauben endet diese Schule für mich nicht einmal einfach mit dem Tod.","Ich habe sehr unterschiedliche Seiten des Lebens erlebt. Ich lebte mit einer Stiefmutter und mit einem Stiefvater. Ich kannte Armut, aber auch Zeiten mit sehr guten finanziellen Möglichkeiten. Es gab Phasen, in denen ich bequem lebte, und Zeiten mit sehr schweren finanziellen Schwierigkeiten.","Was das Leben mir auch brachte, eines wollte ich nicht aufgeben: meine Identität und meinen Charakter. Ich war Angestellter, Leiter und Arbeitgeber und arbeitete in der Gastronomie, in der Produktion und in vielen anderen Bereichen.","Während ich in Deutschland Taxi fuhr, bekam ich gesundheitliche Probleme. Die Folgen einer Operation veränderten mein Leben und führten schließlich dazu, dass ich viel mehr Zeit zu Hause verbrachte.","Es gab noch schwerere Verluste. Mit einer Frau, die ich liebte, bekam ich eine Tochter. Ich verlor meine Tochter. Später verlor ich auch meine Mutter, meinen Vater und Menschen, die ich liebte.","Wenn ich heute zurückblicke, halte ich weder die guten noch die schlechten Zeiten für völlig sinnlos. Ich wusste damals nicht, dass mich all diese Wege eines Tages vor eine Tür bringen würden, die ich mir nie hätte vorstellen können.","Diese Tür sollte später EduVerse heißen."]},{"k":"02 · ALLES BEGANN MIT EINEM GEBET","title":"Eine kleine Botschaft, die ich meiner Tochter schicken wollte","short":"EduVerse begann nicht als Geschäftsidee, sondern mit einem kleinen Gebet, das ich für meine Tochter in den Himmel schicken wollte.","body":["EduVerse begann nicht als große Geschäftsidee. Ich setzte mich auch nicht hin, um ein Spiel zu bauen. Ich konnte nicht programmieren, kannte keine Software und wusste nicht einmal, wie eine App entsteht.","An einem Tag Anfang Mai saß ich zu Hause und dachte an meine verstorbene Tochter. Ich wollte ein Gebet für sie schreiben, es in eine Box legen, in den Himmel steigen lassen und danach Lichter oder Gebete wieder von oben herabschweben sehen.","Für mich bedeutete es nur: „Ich habe dich nicht vergessen.“","Weil ich nicht wusste, wie man so etwas macht, öffnete ich eines der KI-Werkzeuge, die ich im Internet gesehen hatte. Meine erste Frage war: „Sprichst du Türkisch?“ Die Antwort war ja, und ich begann, das System nicht nur wie eine Maschine zu behandeln, sondern wie einen Begleiter, mit dem ich zusammenarbeitete.","Ich erzählte von meiner kleinen Gebetsidee für meine Tochter. Der erste Raum entstand. „Kann das Gebet nach oben steigen?“ Ja. „Kann es versiegelt werden?“ Ja. „Kann die Farbe geändert werden?“ Sie änderte sich. „Kann das auf einen Handybildschirm passen?“ Auch das begann ich zu erforschen.","Jede Antwort brachte eine neue Frage.","Ohne es zu merken, baute ich nicht mehr nur ein Gebet. Ich legte den ersten Stein einer Welt."]},{"k":"03 · EINE WELT LERNEN, DIE ICH NICHT KANNTE","title":"Von Oki bis zu den Robotern","short":"Ich wusste nicht einmal, was ein Asset ist. Ich machte Fehler, glaubte alles verloren zu haben, versuchte es erneut – so wuchs EduVerse.","body":["Nach dem ersten Raum konnte ich nicht aufhören. Ich baute einen weiteren. Am Anfang kamen meine Ideen ganz natürlich aus meinem eigenen Leben und Glauben; ich schuf einen Gebetsraum und dann eine kleine Figur. Sie bekam den Namen Oki.","Ich änderte Okis Farbe, Größe und Bewegungen, versuchte ihn zu füttern und mit einem Kind interagieren zu lassen. Dann sah ich mir andere Spiele an und erkannte, wie schwach meine eigene Figur noch war.","Also begann ich zu lernen, wie Figuren entstehen. Ich wusste nicht einmal, was „Asset“ bedeutet. Ich wusste nicht, warum ein Bild einen transparenten Hintergrund braucht. Ich lernte alles Schritt für Schritt und erstellte Dutzende Charakterbilder.","Dann wurden die Räume größer: Texte, Effekte, Ballons, Puzzle, Reflexspiele und Sprachräume. Ich begann Türkisch, Deutsch, Englisch, Französisch und Arabisch einzubauen.","Natürlich lief nicht immer alles gut. Eines Tages klickte ich an die falsche Stelle und die ganze Plattform wurde zu einem weißen Bildschirm. Ich glaubte, meine Arbeit sei verschwunden, und versuchte viele Stunden lang, alles zu reparieren.","Später erfuhr ich, wie einfach die Lösung eigentlich gewesen wäre. Aber diese 36 Stunden lehrten mich etwas Wichtiges: Etwas nicht zu wissen war nichts, wofür man sich schämen musste; aufzugeben wäre für mich das größere Problem gewesen.","Von da an wurde jeder Fehler zu einer Lektion: FAILED. Noch einmal versuchen. Noch einmal denken. Noch einmal bauen. Und schließlich: PASSED.","So wuchs EduVerse."]},{"k":"04 · MEHR ALS EIN SPIEL","title":"Warum alle Kinder?","short":"Irgendwann fragte ich mich: Warum sollten nur Kinder, die so leben wie ich, davon profitieren?","body":["Am Anfang trug das, was ich baute, Spuren meines eigenen Lebens und Glaubens. Dann stellte ich mir eine wichtige Frage: „Warum sollten nur Kinder, die so leben wie ich, davon profitieren?“","Ein Kind muss nicht muslimisch sein. Es kann in einem anderen Land leben, eine andere Sprache sprechen oder in einer anderen Kultur aufwachsen. Aber Ehrlichkeit, Freundschaft, Teilen, Lernen, Denken, Güte, Selbstvertrauen und Respekt gegenüber anderen Menschen gehören nicht nur einer Religion oder einer Nation.","Damit änderte sich die Richtung von EduVerse. Glaubensbezogene Räume blieben, weil sie auch Teil meiner Geschichte sind. Aber ich baute sie so, dass diese Entscheidungen bei den Eltern liegen.","Gleichzeitig wuchs eine Welt, die allen offensteht: Puzzle, Reflexspiele, Sprachübungen, Aufgaben zum Nachdenken und Bereiche, in denen ein Kind nicht nur auf den Bildschirm tippt, sondern auch Entscheidungen treffen soll.","Heute ist EduVerse eine Plattform mit 33 Räumen. Jeder Raum hat einen anderen Zweck, und ich sehe das Projekt nicht als perfektes, fertiges Produkt, sondern als eine Struktur, die sich ständig weiterentwickeln kann.","Mein eigentliches Ziel ist nicht, ein Kind ein paar Minuten zu beschäftigen. Nach einem Raum soll wenigstens eine kleine gute Idee im Kopf bleiben: einen Freund besser behandeln, eine andere Kultur nicht herabsetzen, ein Wort lernen, ein Problem lösen oder ein wenig mehr an sich glauben.","Wenn nur eines davon geschieht, war dieser Raum für mich nicht umsonst."],"parent":["Bitte achten Sie, so gut Sie können, darauf, was Ihr Kind spielt, sieht und lernt. Schon ein paar Minuten daneben zu sitzen, zu fragen, was es macht, oder gemeinsam etwas zu spielen, kann wertvoller sein, als man denkt.","EduVerse soll Mutter oder Vater nicht ersetzen. Es soll die Bindung unterstützen, die sie mit ihrem Kind aufbauen. Kinder brauchen nicht nur Unterhaltung, sondern auch Zuhören, Verständnis, gute Vorbilder und unsere Zeit.","Bei uns gibt es ein Sprichwort: „Ein Baum wird gebogen, solange er jung ist.“ Eine kleine Güte, ein wenig Wissen oder ein gutes Verhalten aus der Kindheit kann Jahre später Teil des Charakters eines Menschen sein."]},{"k":"05 · WARUM KOSTET EDUVERSE GELD?","title":"Wenn ein Kind Zugang bekommt, ein anderes nicht vergessen","short":"Eine Plattform dauerhaft zu betreiben kostet Geld. Daraus entstanden die Ideen von Askıda EduVerse und dem Goodness Fund.","body":["Am Anfang wollte ich EduVerse völlig kostenlos anbieten, weil ich weiß, dass Millionen Familien auf der Welt nicht dieselben finanziellen Möglichkeiten haben.","Mit der Zeit verstand ich: Eine Plattform zu bauen ist das eine, sie über Jahre am Leben zu halten etwas anderes. Neue Räume, neue Funktionen, technische Dienste, Store-Systeme und künftige sprechende Figuren verursachen reale Kosten.","Darum begann ich statt eines Abonnements über ein möglichst einfaches Modell nachzudenken. Ich wollte niemanden zu monatlichen Zahlungen zwingen. Wer möchte, kann bestimmte Raumpakete kaufen; wer möchte, kann einmal den Vollzugang erwerben.","Daneben entstand für mich eine noch wichtigere Idee: Askıda EduVerse – ein hinterlegter EduVerse-Zugang. Wenn eine Familie EduVerse für das eigene Kind kauft, soll sie auf Wunsch auch einem Kind ohne ausreichende Mittel einen Zugang hinterlassen können.","Wenn EduVerse wächst und Einnahmen und Ausgaben klar sind, möchte ich außerdem einen transparenten Goodness Fund schaffen, in den ein festgelegter Teil meines eigenen Anteils für Kinder fließt. Ein kleiner Betrag reicht vielleicht für eine Mahlzeit, ein größerer Fonds kann die Ausbildung eines Kindes unterstützen, ein noch größerer weitere Leben berühren.","Daraus soll eine weltweite Bewegung der Güte werden. Auch die Idee, im World Hub beitragende Länder sichtbar zu machen, ist daraus entstanden.","Ich möchte außerdem keine unnötigen persönlichen Daten von Familien sammeln. Ich habe Systeme entworfen, bei denen Informationen über die Entwicklung eines Kindes möglichst in den Händen der Familie bleiben; der herunterladbare Familien-PDF-Bericht ist ein Teil davon.","Wenn EduVerse wächst, möchte ich nicht nur sagen können, dass ich mehr verkauft habe. Ich möchte sagen können, dass ich mehr Kinder erreicht habe."]},{"k":"06 · HEUTE UND MORGEN","title":"Ein großer Traum, der in einem kleinen Zimmer begann","short":"Ein kleiner Laptop, acht Monate Arbeit und Gedanken, die nicht stillstanden – dieser Weg endet hier nicht.","body":["Ich baute dieses Projekt nicht in einem großen Büro. Hinter mir stand kein großes Entwicklerteam und kein Labor voller Hochleistungsrechner.","Als jemand, der zeitweise aus gesundheitlichen Gründen kaum das Haus verlassen konnte und von staatlicher Unterstützung lebte, setzte ich mich vor einen kleinen Lenovo-Laptop. Manchmal arbeitete ich stundenlang, manchmal durch die Nacht. Es gab Tage mit einem Stück Kuchen und einem Fruchtsaft, und Tage, an denen ich mich nach guter Arbeit mit einem guten Essen belohnte.","Acht Monate lang lebte ich fast jeden Tag in dieser Welt. Eine Serie, ein Baum vor dem Fenster oder ein einzelner Satz in einem Buch konnten der Anfang einer neuen Idee werden.","Auch heute kann ich mich nicht hinsetzen und aus dem Nichts professionellen Code schreiben. Aber ich lernte, dass ein Werkzeug gut benutzen zu können ebenfalls eine Fähigkeit ist. Ich lernte mit HTML, JavaScript, Python, Node.js, Android-Entwicklungswerkzeugen und vielen Systemen zu arbeiten, deren Namen ich vorher nicht kannte.","Ich weiß auch, dass mit professionellen Engines wie Unity oder Unreal Engine sehr viel anspruchsvollere Spiele möglich sind. Ich kann sie mit der Zeit lernen oder eines Tages mit den richtigen Menschen zusammenarbeiten.","Als die Store-Testphase begann, lernte ich noch eine Lektion über das Leben. Von einigen Menschen in meiner Nähe, von denen ich Hilfe erwartet hatte, bekam ich keine Unterstützung. Dafür nahmen Menschen aus China, Deutschland, Italien, Frankreich, den USA und anderen Teilen der Welt an meinem Test teil. Wenn EduVerse heute diesen Stand erreicht hat, haben auch sie einen kleinen Anteil an dieser Geschichte. Dafür danke ich ihnen.","Und der Weg endet hier nicht. Oki Dede gehört zu meinen Zukunftsplänen – ein älterer Roboter, der Kindern längere Geschichten erzählt und mit ihnen spricht. Ich habe weitere Projekte im Kopf, durch die Kinder beim Spielen die Logik des Programmierens spüren können, und größere Ideen, über die ich noch nicht sprechen möchte.","Vielleicht wird EduVerse sehr groß. Vielleicht bleibt es klein. Aber wenn auch nur ein Kind etwas Gutes daraus mitnimmt, hat es für mich einen Wert. Manchmal beginnen große Veränderungen mit etwas sehr Kleinem.","Auch EduVerse begann so: mit einem kleinen Gebet, das ein Vater seiner verstorbenen Tochter schicken wollte.","Heute geht dieses Gebet nicht mehr nur in den Himmel. Ich möchte, dass es Kinder auf der ganzen Welt erreicht."]}],"final":{"k":"FÜR AYLIN","title":"","body":["Meine Aylin,","Vielleicht kann ich jetzt besser erklären, wo diese Geschichte begonnen hat.","Alles begann mit einem kleinen Gebet, das ich dir schicken wollte. Ich wollte dem Himmel irgendwie sagen, dass ich dich vermisse und dich nicht vergessen habe. Damals wusste ich nicht, dass daraus ein Spiel, eine Plattform oder ein so großer Traum werden würde.","Ich kann dich nicht zurückbringen. Das weiß ich. Aber statt die Liebe zu dir zu verlieren, habe ich versucht, sie in etwas anderes zu verwandeln.","Wenn ein Kind lächelt, etwas Neues lernt, etwas schönere Zeit mit seiner Mutter oder seinem Vater verbringt, wenn sich für ein Kind ohne Möglichkeiten eine Tür öffnet und eine kleine gute Tat zu einer weiteren wird… dann möchte ich, dass darin auch ein Teil von dir lebt.","Der erste Raum von EduVerse wurde für dich geöffnet. Das erste Gebet wurde für dich in den Himmel geschickt. Und egal, wie groß es einmal wird: Am Anfang dieser Geschichte wirst immer du stehen.","Was ich in meinem Leben nicht tun konnte, nicht rechtzeitig erreichte oder unvollständig ließ, kann ich nicht ändern. Aber ich kann versuchen, das, was ich noch tun kann, in etwas Gutes zu verwandeln.","Vielleicht hinterlässt diese Plattform eines Tages etwas Kleines und Gutes im Leben eines Kindes, das ich irgendwo auf der Welt niemals kennenlernen werde.","Dann werde ich innerlich wieder zu dir sagen:","„Schau, meine Aylin… dieses kleine Gebet ist bis hierher gekommen.“","Ich habe dich nicht vergessen. Ich werde dich nie vergessen.","Dein Papa"]}},"fr":{"ui":{"open":"LIRE EN GRAND ÉCRAN","prev":"PRÉCÉDENT","next":"SUIVANT","close":"FERMER","final":"FINAL","readerTitle":"EduVerse · Histoire du fondateur","parentTitle":"Une petite demande aux parents"},"chapters":[{"k":"01 · QUI SUIS-JE ?","title":"Un élève de l’école de la vie","short":"Je suis né à Istanbul le 31 mars 1970. Ma scolarité a été courte ; l’école de la vie, elle, ne s’est jamais arrêtée.","body":["Je m’appelle Tarkan. Je suis né à Istanbul le 31 mars 1970.","Je n’ai pas eu une longue scolarité. J’ai même terminé l’école primaire dans des conditions difficiles. Mais mon apprentissage ne s’est pas arrêté là. Je me suis toujours considéré comme un élève de l’école de la vie et, selon ma propre foi, je crois que cette école ne s’arrête pas simplement avec la mort.","J’ai connu des visages très différents de la vie. J’ai vécu avec une belle-mère et avec un beau-père. J’ai connu la pauvreté, mais aussi des périodes où j’avais de très bons moyens financiers. Il m’est arrivé de vivre confortablement, et j’ai aussi traversé des périodes de très grandes difficultés financières.","Quoi que la vie m’apporte, il y a une chose à laquelle j’ai essayé de ne pas renoncer : mon identité et mon caractère. J’ai été salarié, responsable et patron ; j’ai travaillé dans l’alimentation, la production et beaucoup d’autres domaines.","En Allemagne, alors que je travaillais comme chauffeur de taxi, j’ai eu des problèmes de santé. Les suites d’une opération ont changé ma vie et m’ont conduit à rester beaucoup plus chez moi.","J’ai connu des pertes encore plus lourdes. J’ai eu une fille avec une femme que j’aimais. J’ai perdu ma fille. Plus tard, j’ai aussi perdu ma mère, mon père et des personnes que j’aimais.","Aujourd’hui, quand je regarde en arrière, je ne considère aucune période heureuse ou douloureuse comme totalement dépourvue de sens. Je ne savais pas que toutes ces routes allaient me conduire un jour devant une porte que je n’aurais jamais imaginée.","Cette porte allait s’appeler EduVerse."]},{"k":"02 · TOUT A COMMENCÉ PAR UNE PRIÈRE","title":"Un petit message que je voulais envoyer à ma fille","short":"EduVerse n’est pas né d’une idée d’entreprise, mais d’une petite prière que je voulais envoyer vers le ciel pour ma fille.","body":["EduVerse n’a pas commencé comme une grande idée d’entreprise. Je ne me suis pas assis pour créer un jeu. Je ne connaissais ni le code, ni le logiciel, ni même la façon dont on fabrique une application.","Un jour, au début du mois de mai, assis chez moi, j’ai pensé à ma fille disparue. Je voulais écrire une prière pour elle, la placer dans une boîte, la faire monter vers le ciel et voir ensuite des lumières ou des prières redescendre doucement.","Pour moi, cela voulait simplement dire : « Je ne t’ai pas oubliée. »","Comme je ne savais pas comment faire, j’ai ouvert l’un des outils d’intelligence artificielle que j’avais vus sur Internet. Ma première question a été : « Tu parles turc ? » La réponse a été oui, et j’ai commencé à traiter le système non comme une simple machine, mais comme un compagnon avec lequel je travaillais.","Je lui ai raconté cette petite idée de prière pour ma fille. La première pièce est apparue. « La prière peut-elle monter ? » Oui. « Peut-elle être scellée ? » Oui. « Peut-on changer la couleur ? » Elle a changé. « Peut-on l’adapter à un écran de téléphone ? » J’ai commencé à chercher cela aussi.","Chaque réponse faisait naître une nouvelle question.","Sans m’en rendre compte, je ne préparais plus seulement une prière. Je posais la première pierre d’un monde."]},{"k":"03 · APPRENDRE UN MONDE QUE JE NE CONNAISSAIS PAS","title":"D’Oki aux robots","short":"Je ne savais même pas ce qu’était un asset. J’ai fait des erreurs, cru avoir tout perdu, recommencé : c’est ainsi qu’EduVerse a grandi.","body":["Après la première pièce, je n’ai plus réussi à m’arrêter. J’en ai créé une autre. Au début, mes idées venaient naturellement de ma vie et de ma foi ; j’ai créé un espace de prière puis un petit personnage. Il s’est appelé Oki.","J’ai changé la couleur, la taille et les mouvements d’Oki ; j’ai essayé de le nourrir et de le faire interagir avec un enfant. Ensuite, j’ai regardé d’autres jeux et j’ai compris à quel point mon personnage était encore faible.","Alors j’ai commencé à apprendre comment on crée des personnages. Je ne savais même pas ce que signifiait le mot « asset ». Je ne savais pas pourquoi une image devait avoir un fond transparent. J’ai tout appris pas à pas et créé des dizaines d’images de personnages.","Puis les pièces se sont agrandies : textes, effets, ballons, puzzles, jeux de réflexes et espaces de langues. J’ai commencé à intégrer le turc, l’allemand, l’anglais, le français et l’arabe.","Bien sûr, tout ne fonctionnait pas toujours. Un jour, après avoir cliqué au mauvais endroit, toute la plateforme est devenue un écran blanc. J’ai cru que tout mon travail avait disparu et j’ai passé de longues heures à essayer de réparer.","Plus tard, j’ai appris à quel point la solution était en réalité simple. Mais ces 36 heures m’ont appris quelque chose d’important : ne pas savoir n’était pas une honte ; abandonner aurait été pour moi le vrai problème.","À partir de ce jour, chaque erreur est devenue une leçon : FAILED. Recommencer. Réfléchir encore. Reconstruire. Et finalement : PASSED.","C’est ainsi qu’EduVerse a grandi."]},{"k":"04 · PLUS QU’UN JEU","title":"Pourquoi tous les enfants ?","short":"À un moment, je me suis demandé : pourquoi seuls les enfants qui vivent comme moi devraient-ils en profiter ?","body":["Au début, ce que je créais portait naturellement des traces de ma propre vie et de ma foi. Puis je me suis posé une question importante : « Pourquoi seuls les enfants qui vivent comme moi devraient-ils en profiter ? »","Un enfant peut ne pas être musulman. Il peut vivre dans un autre pays, parler une autre langue ou grandir dans une autre culture. Mais l’honnêteté, l’amitié, le partage, l’apprentissage, la réflexion, la bonté, la confiance en soi et le respect des autres n’appartiennent pas à une seule religion ou à une seule nation.","C’est ainsi que la direction d’EduVerse a changé. Les pièces liées à la foi sont restées, car elles font aussi partie de mon histoire, mais je les ai conçues de manière à laisser ces décisions aux parents.","En parallèle, j’ai développé un monde ouvert à tous : puzzles, jeux de réflexes, apprentissage des langues, tâches qui demandent de réfléchir et espaces où l’enfant ne fait pas que toucher l’écran, mais doit parfois décider.","Aujourd’hui, EduVerse est devenu une plateforme de 33 pièces. Chaque pièce a un objectif différent et je ne le considère pas comme un produit parfait et terminé, mais comme une structure qui peut continuer à évoluer.","Mon vrai but n’est pas d’occuper un enfant quelques minutes. Je veux qu’en sortant d’une pièce, il garde au moins une petite bonne idée : mieux traiter un ami, ne pas mépriser une autre culture, apprendre un mot, résoudre un problème ou avoir un peu plus confiance en lui.","Si une seule de ces choses se produit, alors cette pièce n’aura pas été créée pour rien."],"parent":["Essayez, autant que possible, de suivre ce que votre enfant joue, regarde et apprend. S’asseoir quelques minutes à côté de lui, lui demander ce qu’il fait ou jouer ensemble peut être plus précieux qu’on ne le pense.","Je ne veux pas qu’EduVerse remplace la mère ou le père. Je veux qu’il soutienne le lien qu’ils construisent avec leur enfant. Les enfants n’ont pas seulement besoin de se divertir ; ils ont aussi besoin d’être écoutés, compris, de voir de bons exemples et d’avoir notre temps.","Chez nous, on dit : « L’arbre se façonne lorsqu’il est jeune. » Une petite bonté, une connaissance ou un bon comportement appris pendant l’enfance peut devenir, des années plus tard, une partie du caractère d’une personne."]},{"k":"05 · POURQUOI EDUVERSE EST-IL PAYANT ?","title":"Ne pas oublier un autre enfant lorsqu’un enfant reçoit un accès","short":"Faire vivre la plateforme a un coût ; c’est ainsi qu’ont émergé les idées d’Askıda EduVerse et du Fonds de bonté.","body":["Au début, je voulais proposer EduVerse gratuitement, car je sais que des millions de familles dans le monde n’ont pas les mêmes moyens.","Avec le temps, j’ai compris une chose : créer une plateforme est une chose ; la maintenir en vie pendant des années en est une autre. Les nouvelles pièces, les nouvelles fonctions, les services techniques, les systèmes des boutiques et les futurs personnages qui parlent ont un coût réel.","J’ai donc essayé d’imaginer un système aussi simple que possible, plutôt qu’un abonnement. Je ne voulais pas obliger les gens à payer tous les mois. Ceux qui le souhaitent peuvent acheter certains packs de pièces ; ceux qui préfèrent peuvent acheter une fois l’accès complet.","Mais une autre idée, encore plus importante pour moi, est née : Askıda EduVerse, un accès laissé en attente pour quelqu’un d’autre. Lorsqu’une famille achète EduVerse pour son enfant, elle peut, si elle le souhaite, laisser aussi un accès à un enfant qui n’en a pas les moyens.","Lorsque EduVerse grandira et que les revenus et dépenses seront clairement établis, je veux aussi créer un Fonds de bonté transparent dans lequel une part définie de ma propre part sera réservée aux enfants. Une petite somme peut payer un repas, un fonds plus important soutenir la scolarité d’un enfant, et un fonds encore plus grand toucher d’autres vies.","Je veux en faire un mouvement de bonté auquel le monde entier peut participer. L’idée de rendre visibles dans le World Hub les pays qui contribuent est née de cette pensée.","Je ne souhaite pas non plus collecter inutilement les données personnelles des familles. J’ai conçu des systèmes qui essaient de laisser les informations sur le développement de l’enfant entre les mains de sa famille ; le rapport familial téléchargeable en PDF en fait partie.","Si EduVerse grandit, je ne veux pas seulement dire que j’ai vendu davantage. Je veux dire que j’ai touché davantage d’enfants."]},{"k":"06 · AUJOURD’HUI ET DEMAIN","title":"Un grand rêve né dans une petite pièce","short":"Un petit ordinateur, huit mois de travail et des idées qui ne s’arrêtaient jamais : la route ne se termine pas ici.","body":["Je n’ai pas créé ce projet dans un grand bureau. Je n’avais pas une grande équipe de développeurs derrière moi ni un laboratoire rempli d’ordinateurs puissants.","À une période où ma santé m’empêchait de sortir et où je vivais grâce à une aide de l’État, je me suis assis devant un petit ordinateur portable Lenovo. Parfois je travaillais des heures, parfois toute la nuit. Certains jours je continuais avec simplement un morceau de gâteau et un jus ; d’autres jours, je me récompensais avec un bon repas après un travail dont j’étais satisfait.","Pendant huit mois, j’ai vécu presque chaque jour dans cet univers. Une série, un arbre aperçu par la fenêtre ou une seule phrase dans un livre pouvait devenir le début d’une nouvelle idée.","Aujourd’hui encore, je ne peux pas m’asseoir et écrire de zéro un code professionnel. Mais j’ai appris que savoir bien utiliser un outil est aussi une compétence. J’ai appris à travailler avec HTML, JavaScript, Python, Node.js, les outils de développement Android et de nombreux systèmes dont j’ignorais même le nom.","Je sais aussi que des moteurs professionnels comme Unity ou Unreal Engine permettent de créer des jeux beaucoup plus avancés. Je peux les apprendre avec le temps ou, un jour, travailler avec les bonnes personnes.","Quand l’étape des tests pour les boutiques est arrivée, j’ai appris une autre leçon sur la vie. Je n’ai pas reçu le soutien de certaines personnes proches dont je l’attendais. En revanche, des personnes de Chine, d’Allemagne, d’Italie, de France, des États-Unis et d’autres régions du monde ont participé aux tests. Si EduVerse est arrivé à ce stade aujourd’hui, elles ont elles aussi une petite place dans cette histoire. Je les remercie.","Et la route ne s’arrête pas ici. Oki Dede fait partie de mes projets futurs : un vieux robot que j’imagine raconter de longues histoires aux enfants et parler avec eux. J’ai aussi des projets pour que les enfants puissent ressentir la logique du code tout en jouant, ainsi que de plus grandes idées que je ne veux pas encore révéler.","Peut-être qu’EduVerse deviendra très grand. Peut-être qu’il restera petit. Mais si un seul enfant en retire quelque chose de bon, cela a de la valeur pour moi. Les grands changements commencent parfois par quelque chose de très petit.","EduVerse est né ainsi : d’une petite prière qu’un père voulait envoyer à la fille qu’il avait perdue.","Aujourd’hui, cette prière ne monte plus seulement vers le ciel. Je veux qu’elle atteigne des enfants partout dans le monde."]}],"final":{"k":"POUR AYLIN","title":"","body":["Mon Aylin,","Peut-être que je peux maintenant mieux expliquer où cette histoire a commencé.","Tout a commencé par une toute petite prière que je voulais t’envoyer. Je voulais dire au ciel, d’une manière ou d’une autre, que tu me manquais et que je ne t’avais pas oubliée. Ce jour-là, je ne savais pas que cela deviendrait un jeu, une plateforme ou un rêve aussi grand.","Je ne peux pas te ramener. Je le sais. Mais au lieu de perdre l’amour que j’ai pour toi, j’ai essayé de le transformer en autre chose.","Si un enfant sourit, apprend quelque chose de nouveau, passe un peu plus de bon temps avec sa mère ou son père, si une porte s’ouvre pour un enfant qui a moins de moyens et si une petite bonté en crée une autre… je veux qu’il y ait là aussi une part de toi.","La première pièce d’EduVerse a été ouverte pour toi. La première prière a été envoyée vers le ciel pour toi. Et peu importe jusqu’où ce projet grandira, tu resteras toujours au point de départ de cette histoire.","Je ne peux pas changer ce que je n’ai pas pu faire, ce que je n’ai pas atteint à temps ou ce que j’ai laissé inachevé. Mais je peux essayer de transformer en bien ce qu’il m’est encore possible de faire.","Peut-être qu’un jour cette plateforme laissera une petite chose positive dans la vie d’un enfant que je ne connaîtrai jamais, quelque part dans le monde.","Alors je te dirai encore, au fond de moi :","« Regarde, mon Aylin… cette toute petite prière est arrivée jusqu’ici. »","Je ne t’ai pas oubliée. Je ne t’oublierai jamais.","Papa"]}},"ar":{"ui":{"open":"اقرأ على شاشة كبيرة","prev":"السابق","next":"التالي","close":"إغلاق","final":"الختام","readerTitle":"EduVerse · قصة المؤسس","parentTitle":"طلب صغير إلى الأمهات والآباء"},"chapters":[{"k":"01 · من أنا؟","title":"تلميذ في مدرسة الحياة","short":"وُلدت في إسطنبول في 31 مارس 1970. كانت دراستي النظامية قصيرة، أما مدرسة الحياة فلم تنتهِ.","body":["أنا تاركان. وُلدت في إسطنبول في 31 مارس 1970.","لم أحظَ بتعليم مدرسي طويل، وأنهيت حتى المرحلة الابتدائية في ظروف صعبة. لكن تعلّمي لم ينتهِ هناك. كنت أرى نفسي دائماً تلميذاً في مدرسة الحياة، ووفق إيماني الشخصي أعتقد أن هذه المدرسة لا تنتهي ببساطة حتى بالموت.","رأيت وجوهاً مختلفة جداً للحياة. عشت مع زوجة أب ومع زوج أم. عرفت الفقر، وعشت أيضاً فترات كانت فيها إمكاناتي المادية جيدة جداً. مرت عليّ أيام عشت فيها براحة، وأيام مررت فيها بصعوبات مالية شديدة.","مهما جلبت لي الحياة، حاولت ألا أتنازل عن شيء واحد: هويتي وشخصيتي. كنت موظفاً ومديراً وصاحب عمل، وعملت في مجال الطعام والإنتاج وأعمال أخرى كثيرة.","أثناء عملي سائق تاكسي في ألمانيا ظهرت لدي مشكلات صحية. غيّرت آثار عملية جراحية حياتي، حتى أصبحت أمضي وقتاً أكبر في المنزل.","وكانت هناك خسائر أثقل من ذلك بكثير. رُزقت بابنة من امرأة أحببتها. فقدت ابنتي. ثم فقدت في فترات مختلفة أمي وأبي وأشخاصاً أحببتهم.","واليوم، عندما أنظر إلى الماضي، لا أرى أي مرحلة جيدة أو سيئة في حياتي بلا معنى تماماً. لم أكن أعرف أن كل تلك الطرق ستقودني يوماً إلى باب لم أتخيله قط.","ذلك الباب سيحمل لاحقاً اسم EduVerse."]},{"k":"02 · كل شيء بدأ بدعاء","title":"رسالة صغيرة أردت أن أرسلها إلى ابنتي","short":"لم يبدأ EduVerse كفكرة شركة، بل بدعاء صغير أردت أن أرسله إلى السماء من أجل ابنتي.","body":["لم يبدأ EduVerse كفكرة شركة كبيرة، ولم أجلس لأصنع لعبة. لم أكن أعرف البرمجة أو تطوير البرامج، ولم أكن أعرف حتى كيف يُبنى تطبيق.","في يوم من أوائل شهر مايو، كنت جالساً في المنزل وأفكر في ابنتي الراحلة. أردت أن أكتب لها دعاءً، أضعه في صندوق ويرتفع نحو السماء، ثم تنزل من الأعلى أضواء أو أدعية من جديد.","كان معنى ذلك بالنسبة لي بسيطاً: «لم أنسكِ.»","لأنني لم أكن أعرف كيف يمكن تنفيذ ذلك، فتحت واحدة من أدوات الذكاء الاصطناعي التي رأيتها على الإنترنت. كان أول سؤال لي: «هل تتحدث التركية؟» جاءت الإجابة نعم، وبدأت أتعامل مع النظام لا كآلة فقط، بل كرفيق أعمل معه.","ورويت له فكرة الدعاء الصغير الذي تخيلته لابنتي. ظهرت الغرفة الأولى. «هل يمكن أن يرتفع الدعاء؟» نعم. «هل يمكن أن يُختم؟» نعم. «هل يمكن تغيير اللون؟» تغيّر. «هل يمكن أن يناسب شاشة الهاتف؟» وبدأت أبحث عن ذلك أيضاً.","كل إجابة كانت تفتح في ذهني سؤالاً جديداً.","من دون أن أشعر، لم أعد أصنع دعاءً فقط. كنت أضع الحجر الأول لعالم كامل."]},{"k":"03 · تعلّم عالم لم أكن أعرفه","title":"من Oki إلى الروبوتات","short":"لم أكن أعرف حتى معنى Asset. أخطأت، ظننت أنني فقدت كل شيء، ثم حاولت من جديد؛ وهكذا نما EduVerse.","body":["بعد الغرفة الأولى لم أستطع التوقف. أنشأت غرفة أخرى. في البداية كانت أفكاري تأتي بشكل طبيعي من حياتي وإيماني؛ أنشأت غرفة للعبادة ثم شخصية صغيرة. أصبح اسمها Oki.","غيّرت لون Oki وحجمه وحركاته، وحاولت أن أجعله يأكل ويتفاعل مع الطفل. ثم نظرت إلى ألعاب أخرى ورأيت أن شخصيتي ما زالت ضعيفة جداً مقارنة بها.","فبدأت أتعلم كيف تُصنع الشخصيات. لم أكن أعرف حتى معنى كلمة Asset، ولم أكن أعرف لماذا تحتاج الصورة إلى خلفية شفافة. تعلمت كل ذلك خطوة خطوة وأنشأت عشرات صور الشخصيات.","ثم بدأت الغرف تكبر: نصوص، مؤثرات، بالونات، ألغاز، ألعاب رد الفعل وغرف اللغات. وبدأت بإضافة التركية والألمانية والإنجليزية والفرنسية والعربية.","وبالطبع لم تسر الأمور دائماً كما أردت. في يوم ضغطت في المكان الخطأ فتحولت المنصة كلها إلى شاشة بيضاء. ظننت أن عملي كله اختفى، وحاولت إصلاحه لساعات طويلة.","ثم عرفت لاحقاً كم كان الحل بسيطاً في الحقيقة. لكن تلك الساعات علمتني شيئاً مهماً: عدم المعرفة ليس عيباً؛ الاستسلام كان سيكون المشكلة الأكبر بالنسبة لي.","ومنذ ذلك اليوم أصبح كل خطأ درساً: FAILED. حاول مرة أخرى. فكر مرة أخرى. ابنِ مرة أخرى. وفي النهاية: PASSED.","هكذا نما EduVerse."]},{"k":"04 · أكثر من لعبة","title":"لماذا كل الأطفال؟","short":"في مرحلة ما سألت نفسي: لماذا يستفيد من هذا فقط الأطفال الذين يعيشون مثلي؟","body":["في البداية كان ما أصنعه يحمل آثار حياتي وإيماني بشكل طبيعي. ثم سألت نفسي سؤالاً مهماً: «لماذا يستفيد من هذا فقط الأطفال الذين يعيشون مثلي؟»","قد لا يكون الطفل مسلماً. وقد يعيش في بلد آخر أو يتحدث لغة أخرى أو يكبر في ثقافة مختلفة. لكن الصدق والصداقة والمشاركة والتعلم والتفكير وفعل الخير والثقة بالنفس واحترام الآخرين ليست قيماً تخص ديناً واحداً أو أمة واحدة.","من هنا تغيّر اتجاه EduVerse. بقيت الغرف المرتبطة بالإيمان لأنها جزء من قصتي أيضاً، لكنني صممتها بحيث تبقى هذه القرارات في يد الوالدين.","وفي الوقت نفسه وسعت عالماً مفتوحاً للجميع: ألغاز، ألعاب رد فعل، تعلم لغات، مهام تحتاج إلى التفكير، وأقسام لا يلمس فيها الطفل الشاشة فقط بل يتخذ قرارات أحياناً.","اليوم أصبح EduVerse منصة تضم 33 غرفة. ولكل غرفة هدف مختلف، وأنا لا أراه منتجاً كاملاً منتهياً، بل بنية يمكنها أن تستمر في التطور.","هدفي الحقيقي ليس إشغال الطفل بضع دقائق. أريد أن يبقى في ذهنه بعد الخروج من الغرفة شيء جيد ولو صغيراً: أن يعامل صديقه بشكل أفضل، وألا يحتقر ثقافة أخرى، وأن يتعلم كلمة، أو يحل مشكلة، أو يثق بنفسه أكثر قليلاً.","إذا تحقق واحد فقط من هذه الأشياء، فهذه الغرفة لم تُبنَ عبثاً بالنسبة لي."],"parent":["حاولوا قدر الإمكان أن تعرفوا ما الذي يلعبه طفلكم وما الذي يشاهده وما الذي يتعلمه. الجلوس إلى جانبه بضع دقائق، وسؤاله عما يفعل، أو اللعب معه قد يكون أثمن مما نتصور.","لا أريد من EduVerse أن يحل محل الأم أو الأب، بل أن يدعم العلاقة التي يبنيانها مع طفلهما. الأطفال لا يحتاجون إلى الترفيه فقط؛ بل يحتاجون أيضاً إلى من يسمعهم ويفهمهم ويقدم لهم أمثلة جيدة ويمنحهم من وقته.","لدينا قول جميل معناه أن الشجرة تُشكّل وهي صغيرة. قد تتحول كلمة طيبة أو معرفة صغيرة أو سلوك جيد يتعلمه الطفل اليوم إلى جزء من شخصيته بعد سنوات."]},{"k":"05 · لماذا EduVerse مدفوع؟","title":"عندما يحصل طفل على فرصة، لا ننسى طفلاً آخر","short":"استمرار المنصة يحتاج إلى تكلفة، ومن هنا وُلدت فكرتا Askıda EduVerse وصندوق الخير.","body":["في البداية أردت أن يكون EduVerse مجانياً بالكامل، لأنني أعرف أن ملايين العائلات في العالم لا تملك الإمكانات المادية نفسها.","لكنني فهمت مع الوقت أن إنشاء منصة شيء، والحفاظ عليها حية لسنوات شيء آخر. الغرف الجديدة والميزات الجديدة والخدمات التقنية وأنظمة المتاجر والشخصيات التي ستتحدث مستقبلاً لها تكاليف حقيقية.","لذلك بدأت أفكر في نظام بسيط قدر الإمكان بدلاً من الاشتراك الشهري. لم أرد أن أجبر الناس على الدفع كل شهر. من يريد يمكنه شراء حزم محددة من الغرف، ومن يريد يمكنه شراء الوصول الكامل مرة واحدة.","لكن بجانب ذلك وُلدت لدي فكرة أهم: Askıda EduVerse، أي أن يترك شخص وصولاً إلى EduVerse لطفل آخر. عندما تشتري عائلة EduVerse لطفلها، يمكنها إن رغبت أن تترك أيضاً وصولاً لطفل لا يملك الإمكانات.","وعندما يكبر EduVerse وتتضح الإيرادات والمصروفات، أريد أيضاً إنشاء صندوق خير شفاف تُخصص فيه نسبة محددة من حصتي أنا للأطفال. ربما يكفي مبلغ صغير لوجبة طفل، وقد يساهم صندوق أكبر في تعليم طالب، وقد يلمس صندوق أكبر حياة أشخاص آخرين.","وأريد أن يتحول ذلك إلى حركة خير يشارك فيها العالم كله. ومن هنا جاءت أيضاً فكرة إظهار الدول المساهمة داخل World Hub.","كما أنني لا أريد جمع بيانات شخصية غير ضرورية من العائلات. صممت أنظمة تحاول إبقاء معلومات تطور الطفل قدر الإمكان في يد العائلة نفسها؛ والتقرير العائلي القابل للتنزيل بصيغة PDF جزء من ذلك.","إذا نما EduVerse، فلا أريد أن يكون معنى ذلك أنني بعت أكثر فقط. أريد أن يكون معناه أنني وصلت إلى أطفال أكثر."]},{"k":"06 · اليوم وغداً","title":"حلم كبير بدأ في غرفة صغيرة","short":"حاسوب محمول صغير، ثمانية أشهر من العمل وأفكار لا تتوقف؛ هذا الطريق لا ينتهي هنا.","body":["لم أبنِ هذا المشروع في مكتب كبير. لم يكن خلفي فريق برمجي ضخم، ولم يكن لدي مختبر مليء بأجهزة قوية.","في فترة كنت فيها غير قادر على الخروج من المنزل بسبب صحتي وأعيش على دعم من الدولة، جلست أمام حاسوب Lenovo محمول صغير. عملت أحياناً لساعات وأحياناً طوال الليل. كانت هناك أيام واصلت فيها العمل بقطعة كعك وعصير فقط، وأيام كافأت فيها نفسي بوجبة جيدة بعد عمل شعرت أنني أنجزته بشكل جيد.","ثمانية أشهر تقريباً عشت داخل هذا العالم كل يوم. مسلسل، أو شجرة خارج النافذة، أو جملة واحدة في كتاب كانت قد تصبح بداية لفكرة جديدة.","حتى اليوم لا أستطيع الجلوس وكتابة برنامج احترافي من الصفر. لكنني تعلمت أن القدرة على استخدام الأداة جيداً هي مهارة أيضاً. تعلمت العمل مع HTML وJavaScript وPython وNode.js وأدوات تطوير Android وأنظمة كثيرة لم أكن أعرف أسماءها من قبل.","وأعرف أيضاً أن محركات احترافية مثل Unity أو Unreal Engine تسمح بألعاب أكثر تقدماً بكثير. يمكنني أن أتعلمها مع الوقت أو أعمل في المستقبل مع الأشخاص المناسبين.","وعندما وصلت إلى مرحلة الاختبار للمتاجر تعلمت درساً آخر في الحياة. لم أحصل على دعم من بعض الأشخاص القريبين الذين توقعت منهم المساعدة، بينما شارك أشخاص من الصين وألمانيا وإيطاليا وفرنسا والولايات المتحدة وأماكن أخرى من العالم في الاختبار. إذا كان EduVerse قد وصل اليوم إلى هذه المرحلة، فلهؤلاء أيضاً جزء صغير في هذه القصة. أشكرهم.","والطريق لا ينتهي هنا. ومن خططي المستقبلية Oki Dede، وهو روبوت مسن أتخيله يروي للأطفال قصصاً طويلة ويتحدث معهم. ولدي مشاريع أخرى تجعل الأطفال يشعرون بمنطق البرمجة أثناء اللعب، وأفكار أكبر لا أريد كشفها بعد.","ربما يكبر EduVerse كثيراً، وربما يبقى صغيراً. لكن إذا أخذ طفل واحد فقط شيئاً جيداً منه، فهذا له قيمة عندي. أحياناً تبدأ التغييرات الكبيرة من بداية صغيرة جداً.","وهكذا وُلد EduVerse أيضاً: من دعاء صغير أراد أب أن يرسله إلى ابنته التي فقدها.","واليوم لم يعد ذلك الدعاء يصعد نحو السماء فقط. أريد أن يصل إلى أطفال في كل أنحاء العالم."]}],"final":{"k":"إلى آيلين","title":"","body":["ابنتي آيلين،","ربما أستطيع الآن أن أشرح بشكل أفضل من أين بدأت هذه القصة.","كل شيء بدأ بدعاء صغير جداً أردت أن أرسله إليك. أردت بطريقة ما أن أقول للسماء إنني أشتاق إليك وإنني لم أنسكِ. لم أكن أعرف في ذلك اليوم أن هذا سيتحول إلى لعبة أو منصة أو حلم بهذا الحجم.","لا أستطيع أن أعيدكِ. أعرف ذلك. لكن بدلاً من أن أفقد الحب الذي أحمله لكِ، حاولت أن أحوله إلى شيء آخر.","إذا ابتسم طفل، أو تعلم شيئاً جديداً، أو قضى وقتاً أجمل قليلاً مع أمه أو أبيه، أو فُتح باب لطفل لا يملك الإمكانات، أو تحولت حسنة صغيرة إلى حسنة أخرى… فأنا أريد أن يكون لكِ جزء في ذلك.","أول غرفة في EduVerse فُتحت من أجلكِ. وأول دعاء أُرسل إلى السماء من أجلكِ. ومهما كبر هذا المشروع، ستبقين دائماً عند نقطة بداية هذه القصة.","لا أستطيع تغيير ما لم أستطع فعله أو ما لم ألحق به أو ما تركته ناقصاً في حياتي. لكنني أستطيع أن أحاول تحويل ما يمكنني فعله من الآن فصاعداً إلى خير.","ربما تترك هذه المنصة يوماً ما شيئاً جيداً ولو صغيراً في حياة طفل لا أعرفه في مكان آخر من العالم.","وعندها سأقول لكِ في داخلي مرة أخرى:","«انظري يا آيلين… ذلك الدعاء الصغير وصل إلى هنا.»","لم أنسكِ. ولن أنساكِ.","أبوكِ"]}}};
var root=null,modal=null,scroll=null,idx=0,lastFocus=null,lastLang='';
var chapterNodes=[];

function lang(){
  var x=(d.body&&d.body.dataset&&d.body.dataset.eduLang)||d.documentElement.lang||'tr';
  return STORY[x]?x:'tr';
}
function T(){return STORY[lang()]||STORY.tr;}
function esc(s){return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function setText(n,v){if(n&&n.textContent!==v)n.textContent=v;}

function ensureModal(){
  if(modal)return;
  modal=d.createElement('div');
  modal.className='story-reader';
  modal.hidden=true;
  modal.innerHTML=''
   +'<div class="story-reader__backdrop" data-reader-close></div>'
   +'<section class="story-reader__panel" role="dialog" aria-modal="true" aria-labelledby="storyReaderHeading">'
   +'<header class="story-reader__top"><div><span class="story-reader__brand" data-reader-ui="readerTitle"></span><small data-reader-count></small></div><button type="button" class="story-reader__x" data-reader-close>×</button></header>'
   +'<div class="story-reader__scroll" data-reader-scroll tabindex="0"></div>'
   +'<footer class="story-reader__footer"><button type="button" data-reader-prev></button><button type="button" class="story-reader__close" data-reader-close></button><button type="button" class="story-reader__next" data-reader-next></button></footer>'
   +'</section>';
  d.body.appendChild(modal);
  scroll=modal.querySelector('[data-reader-scroll]');
  modal.addEventListener('click',function(e){
    if(e.target.closest('[data-reader-close]'))closeReader();
    if(e.target.closest('[data-reader-prev]'))go(-1);
    if(e.target.closest('[data-reader-next]'))go(1);
  });
}

function applyCards(){
  root=d.getElementById('founderStory');if(!root)return false;
  chapterNodes=Array.prototype.slice.call(root.querySelectorAll('.founder-story__chapter')).slice(0,6);
  if(chapterNodes.length<6)return false;
  var t=T();
  chapterNodes.forEach(function(ch,i){
    var c=t.chapters[i];
    var k=ch.querySelector('[data-story="chapter'+(i+1)+'K"]');
    var h=ch.querySelector('[data-story="chapter'+(i+1)+'T"]');
    var p=ch.querySelector('[data-story="chapter'+(i+1)+'D"]');
    setText(k,c.k);setText(h,c.title);setText(p,c.short);
    ch.dataset.readerIndex=String(i);
    ch.classList.add('story-reader-trigger');
    var b=ch.querySelector('.story-reader-open');
    if(!b){
      b=d.createElement('button');b.type='button';b.className='story-reader-open';
      b.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();openReader(i,b);});
      ch.appendChild(b);
    }
    setText(b,t.ui.open);
    b.setAttribute('aria-label',t.ui.open+' · '+c.k+' · '+c.title);
  });
  lastLang=lang();
  return true;
}

function render(){
  ensureModal();
  var t=T(),isFinal=idx===6,page=isFinal?t.final:t.chapters[idx];
  modal.classList.toggle('is-aylin',isFinal);
  modal.dir=(lang()==='ar')?'rtl':'ltr';
  modal.querySelector('[data-reader-ui="readerTitle"]').textContent=t.ui.readerTitle;
  var countEl=modal.querySelector('[data-reader-count]');
  countEl.textContent=isFinal?t.ui.final:(String(idx+1).padStart(2,'0')+' / 06');
  countEl.setAttribute('dir',(isFinal&&lang()==='ar')?'rtl':'ltr');
  countEl.style.unicodeBidi='isolate';
  modal.querySelector('[data-reader-prev]').textContent=t.ui.prev;
  modal.querySelector('.story-reader__close').textContent=t.ui.close;
  modal.querySelector('[data-reader-next]').textContent=t.ui.next;
  modal.querySelector('.story-reader__x').setAttribute('aria-label',t.ui.close);
  modal.querySelector('[data-reader-prev]').disabled=(idx===0);
  modal.querySelector('[data-reader-next]').disabled=isFinal;

  var html='<article class="story-reader__article"><span class="story-reader__kicker">'+esc(page.k)+'</span><h2 id="storyReaderHeading">'+esc(page.title||page.k)+'</h2>';
  if(!isFinal&&page.title)html+='<div class="story-reader__rule" aria-hidden="true"></div>';
  page.body.forEach(function(p,pi){
    var cls='';
    if(isFinal&&pi===0)cls=' class="story-reader__salute"';
    if(isFinal&&pi===9)cls=' class="story-reader__aylin-line"';
    if(isFinal&&pi===11)cls=' class="story-reader__signature"';
    html+='<p'+cls+'>'+esc(p)+'</p>';
  });
  if(!isFinal&&page.parent){
    html+='<aside class="story-reader__parent"><h3>'+esc(t.ui.parentTitle)+'</h3>';
    page.parent.forEach(function(p){html+='<p>'+esc(p)+'</p>';});
    html+='</aside>';
  }
  html+='</article>';
  scroll.innerHTML=html;
  scroll.scrollTop=0;
}

function openReader(i,focusEl){
  ensureModal();
  idx=Math.max(0,Math.min(6,Number(i)||0));
  lastFocus=focusEl||d.activeElement;
  if(w.EDUVERSE_STORY&&typeof w.EDUVERSE_STORY.pause==='function')w.EDUVERSE_STORY.pause();
  applyCards();
  render();
  modal.hidden=false;d.documentElement.classList.add('story-reader-opened');
  w.requestAnimationFrame(function(){modal.classList.add('is-open');scroll.focus({preventScroll:true});});
}
function closeReader(){
  if(!modal||modal.hidden)return;
  modal.classList.remove('is-open');d.documentElement.classList.remove('story-reader-opened');
  w.setTimeout(function(){modal.hidden=true;if(lastFocus&&lastFocus.focus)lastFocus.focus({preventScroll:true});},180);
}
function go(delta){var ni=idx+delta;if(ni<0||ni>6)return;idx=ni;render();}

function init(){
  ensureModal();
  var tries=0;
  (function mount(){tries++;if(applyCards())return;if(tries<80)w.setTimeout(mount,50);})();
  d.addEventListener('keydown',function(e){
    if(!modal||modal.hidden)return;
    if(e.key==='Escape'){e.preventDefault();closeReader();}
    else if(e.key==='ArrowRight'){e.preventDefault();go(lang()==='ar'?-1:1);}
    else if(e.key==='ArrowLeft'){e.preventDefault();go(lang()==='ar'?1:-1);}
  });
  if(d.body)new MutationObserver(function(){
    var l=lang();
    if(l!==lastLang)w.setTimeout(function(){applyCards();if(modal&&!modal.hidden)render();},0);
  }).observe(d.body,{attributes:true,attributeFilter:['data-edu-lang']});
  var syncTimer=0;
  if(root)new MutationObserver(function(){
    if(syncTimer)return;
    syncTimer=w.setTimeout(function(){syncTimer=0;applyCards();},0);
  }).observe(root,{subtree:true,childList:true,characterData:true});
}
if(d.readyState==='loading')d.addEventListener('DOMContentLoaded',init,{once:true});else init();
w.EDUVERSE_STORY_READER={open:function(i){openReader(i||0,null);},close:closeReader,state:function(){return{open:!!(modal&&!modal.hidden),page:idx,language:lang()};}};
})(window,document);
